 Actor denied=player();Zombie dz=zombie(denied);dz.deny=true;denied.look=head.look;int before=dz.state;Stomp18.stomp(denied,1);tick(denied,9);ok(dz.state==before&&dz.alive&&denied.w.particles==0&&cue()==21,"protected damage restores head and produces no hit FX");
